create temporary view chat_history_${grass_region_without_quote} as
select
    round_id
    ,coalesce(
        date(from_unixtime(cast(get_json_object(history_details, '$.request.timestamp') as bigint)/1000)),
        date'2024-08-25'
    ) as regional_date -- records before 0826 are combined together because timestamp is not available
    ,if(get_json_object(history_details, '$.response.data.is_safe') = 'false' or get_json_object(history_details, '$.request.is_safe') = 'false', 1, 0) as is_flagged
    ,get_json_object(history_details, '$.request.utterance') as prompt_text
    ,coalesce(
        filter(
            transform(
                from_json(get_json_object(history_details, '$.response.data.answer'), 'ARRAY<string>'),
                x -> case when get_json_object(x, '$.bubble_type') = 'item_full' then get_json_object(x, '$.item_full.frontier_md')
                          when get_json_object(x, '$.bubble_type') = 'item_lite' then get_json_object(x, '$.item_lite.frontier_md')
                          when get_json_object(x, '$.bubble_type') = 'item_rcmd' then get_json_object(x, '$.item_rcmd.frontier_md')
                          when get_json_object(x, '$.bubble_type') = 'apprl' then get_json_object(x, '$.apprl.frontier_md')
                          when get_json_object(x, '$.bubble_type') = 'text' then get_json_object(x, '$.text.content_md')
                          else null end
            ),
            y -> y is not null
        ),
        array()
    ) as response_text
    ,cast(get_json_object(history_details, '$.request.request_meta.userid') as bigint) as user_id
    ,cast(get_json_object(history_metas, '$.response_code') as bigint) as response_code
    ,get_json_object(history_metas, '$.fallback_answer') as fallback_answer
    ,cast(get_json_object(history_metas, '$.hit_safe_reason') as int) as hit_safe_reason
    ,coalesce(
        filter(
            from_json(get_json_object(history_metas, '$.hit_keywords'), 'ARRAY<string>'),
            x -> coalesce(x, '') != ''
        ),
        array()
    ) as hit_keywords_list
    ,biz_session_id
from
    srdi_mart.dwd_sr_data_warehouse_video_chat_log
where
    grass_region = ${grass_region}
    and (
        (${local_date} >= '2024-09-15' and (dt between date_sub(${local_date}, 89) and ${local_date}))
        or (dt <= '2024-09-14')
    ) -- dt > manual check date for re-ingested data so cannot use the first filter
    and round_id is not null
    and get_json_object(history_details, '$.response.data.is_safe') in ('true', 'false')
    and (
        (dt = '2024-09-14' and hour = 15)
        or get_json_object(history_details, '$.request.timestamp') is not null
    ) -- records before 0826 have no timestamp, so keep records with null timestamp in the full data ingestion
;

