create temporary view manual_result_base_${grass_region_without_quote} as
select
    manual_ticket_id
    ,queue_id
    ,from_json(
        get_json_object(result_element, '$.detail')
        ,'STRUCT<
            pms_ext_detail_list: ARRAY<
                STRUCT<
                    key_id: STRING,
                    pms_label: ARRAY<STRUCT<title: STRING>>
                >
            >
        >'
    ).pms_ext_detail_list as pms_ext_detail_list
    ,operator
from
    qc.shopee_luckyvideo_qc_manual_id_db__manual_ticket_result_tab__reg_continuous_s0_live
lateral view outer explode(from_json(get_json_object(result_info, '$.ext'), 'ARRAY<string>')) as result_element
where
    queue_id in (1000000011, 1000000067) -- old queue and new queue respectively
    and date(from_unixtime(ctime/1000)) = ${local_date}
    and get_json_object(result_element, '$.label_type') = 2
;

--sql_divide_splitter--
create temporary view manual_result_${grass_region_without_quote} as
select
    manual_ticket_id
    ,queue_id
    ,if(queue_id = 1000000011, coalesce(pms_ext_detail_list[0].pms_label.title, array()), array()) as policy_array
    ,if(queue_id = 1000000067, coalesce(filter(pms_ext_detail_list, x -> x['key_id']=1094)[0].pms_label.title, array()), array()) as prompt_policy_array
    ,if(queue_id = 1000000067, coalesce(filter(pms_ext_detail_list, x -> x['key_id']=1095)[0].pms_label.title, array()), array()) as response_policy_array
    ,operator
from
    manual_result_base_${grass_region_without_quote}
;

