create temporary view manual_result_joined_${grass_region_without_quote} as
select
    t2.round_id
    ,queue_id
    ,array_distinct(flatten(collect_list(t1.policy_array))) as policy_list
    ,array_distinct(flatten(collect_list(t1.prompt_policy_array))) as prompt_policy_list
    ,array_distinct(flatten(collect_list(t1.response_policy_array))) as response_policy_list
    ,min(t3.sample_type) as sample_type -- one distinct sample_type per round_id
    ,array_distinct(collect_list(t1.operator)) as operator_list
from
    manual_result_${grass_region_without_quote} as t1 -- manual_ticket_id, policy_array, prompt_policy_array, response_policy_array, operator
inner join
    manual_ticket_round_id_mapping_${grass_region_without_quote} as t2 -- manual_ticket_id, round_id
on
    t1.manual_ticket_id = t2.manual_ticket_id
left join sample_type_mapping_${grass_region_without_quote} as t3 -- manual_ticket_id, sample_type
    on t1.manual_ticket_id = t3.manual_ticket_id
group by
    round_id, queue_id
;

