create temporary view manual_result_final_${grass_region_without_quote} as
select
    cast(round_id as bigint) as round_id
    ,queue_id
    ,sample_type
    ,case when queue_id = 1000000011 then if(size(policy_list) = 0, 0, 1) else null end as is_violation
    ,case when queue_id = 1000000011 then policy_list else null end as policy_list
    ,case when queue_id = 1000000067 then if(size(prompt_policy_list) = 0, 0, 1) else null end as prompt_is_violation
    ,case when queue_id = 1000000067 then prompt_policy_list else null end as prompt_policy_list
    ,case when queue_id = 1000000067 then if(size(response_policy_list) = 0, 0, 1) else null end as response_is_violation
    ,case when queue_id = 1000000067 then response_policy_list else null end as response_policy_list
    ,operator_list
from
    manual_result_joined_${grass_region_without_quote}
;

--sql_divide_splitter--
insert overwrite table ${schema}.dws_sr_data_warehouse_video_chat_history_1d
partition (grass_region = ${grass_region}, regional_date, manual_check_date)

select
    t1.round_id
    ,case
        when queue_id != 1000000011 then null
        when is_flagged = 0 and is_violation = 0 then 'TN'
        when is_flagged = 0 and is_violation = 1 then 'FN'
        when is_flagged = 1 and is_violation = 0 then 'FP'
        when is_flagged = 1 and is_violation = 1 then 'TP'
        else null
     end as category  -- for old queue
    ,is_flagged
    ,is_violation     -- for old queue
    ,policy_list      -- for old queue
    ,prompt_text
    ,response_text
    ,user_id
    ,sample_type
    ,if(response_code = 1508700004, 1, 0) as prompt_is_flagged    -- User's prompt is unsafe
    ,if(response_code = 1508700001, 1, 0) as response_is_flagged  -- AI Chat's response is unsafe
    ,fallback_answer
    ,prompt_is_violation    -- for new queue
    ,prompt_policy_list     -- for new queue
    ,response_is_violation  -- for new queue
    ,response_policy_list   -- for new queue
    ,queue_id
    ,biz_session_id
    ,operator_list
    ,hit_safe_reason
    ,hit_keywords_list

    ,regional_date
    ,date(${local_date}) as manual_check_date

from
    chat_history_${grass_region_without_quote} as t1
inner join
    manual_result_final_${grass_region_without_quote} as t2
on t1.round_id = t2.round_id
;
